INSERT INTO setting (id, type, value, note) VALUES ('island.grid.cell-size', 'int', '400', 'Distance between island centres, in blocks. Every island also owns the same cell in the separate sb_nether.');
INSERT INTO setting (id, type, value, note) VALUES ('island.grid.island-y', 'int', '64', 'World Y of the top layer of every island (players stand one block higher).');
INSERT INTO setting (id, type, value, note) VALUES ('island.grid.edge-margin', 'int', '2', 'The biggest border radius is clamped to cell-size/2 minus this margin so two islands can never touch.');
INSERT INTO setting (id, type, value, note) VALUES ('island.hub.enabled', 'bool', 'true', 'Legacy configuration only: the live Skyblock never builds a hub.');
INSERT INTO setting (id, type, value, note) VALUES ('island.hub.y', 'int', '100', 'World Y of the plaza surface.');
INSERT INTO setting (id, type, value, note) VALUES ('island.hub.max-blocks', 'int', '45000', 'Hard cap on the number of blocks the hub generator may place (the generator stops adding when reached).');
INSERT INTO setting (id, type, value, note) VALUES ('island.hub.allow-interact', 'bool', 'true', 'false = no full hub: only the small spawn pad is built (islandless players and the void rescue still need it). Players may press buttons / open doors in the hub (never break or place).');
INSERT INTO setting (id, type, value, note) VALUES ('island.generation.blocks-per-tick', 'int', '3000', 'Blocks placed (or cleared) per server tick by the batch builder, and a time ceiling per tick in milliseconds.');
INSERT INTO setting (id, type, value, note) VALUES ('island.generation.max-millis-per-tick', 'int', '20', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.generation.chunk-timeout-ticks', 'int', '600', 'A job that has waited this many ticks for chunks is abandoned.');
INSERT INTO setting (id, type, value, note) VALUES ('island.generation.retries', 'int', '3', 'A failed island build, platform build or wipe is retried this many times (0 = never), waiting retry-delay-ticks and doubling the wait each time. After that the island stays unfinished (RESETTING or BUILDING), the owner and online admins are told, and /islandadmin rebuild (or the next restart) retries.');
INSERT INTO setting (id, type, value, note) VALUES ('island.generation.retry-delay-ticks', 'int', '100', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.starter-chest.once-per-player', 'bool', 'true', 'Fill the starter chest (and the Nether/End ruin chests) only the first time a player gets an island, so "reset and recreate" cannot farm loot.');
INSERT INTO setting (id, type, value, note) VALUES ('island.platforms.end-gate-lit', 'bool', 'true', 'Legacy field: End gates are no longer generated, regardless of this value.');
INSERT INTO setting (id, type, value, note) VALUES ('island.protection.trusted-containers', 'bool', 'false', 'Trusted guests may open containers even when the island''s visitor_chests setting is off.');
INSERT INTO setting (id, type, value, note) VALUES ('island.protection.message-cooldown-ms', 'int', '1500', 'Cooldown between two "you cannot do that" messages, in milliseconds.');
INSERT INTO setting (id, type, value, note) VALUES ('island.protection.visitor-pickup', 'bool', 'false', 'Visitors (and banned players) may pick up items lying on someone else''s island (items they threw themselves are always theirs) / may drop items there.');
INSERT INTO setting (id, type, value, note) VALUES ('island.protection.visitor-drop', 'bool', 'false', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.protection.join-check-delay-ticks', 'int', '120', 'A player who logs in standing on an island they may not enter (banned or the island was locked while they were offline) is moved out after this many ticks. Longer than the join router''s cross-server handoff.');
INSERT INTO setting (id, type, value, note) VALUES ('island.border.visual', 'bool', 'true', 'Per-player visual border at the island radius (client side) and the server-side enforcement behind it.');
INSERT INTO setting (id, type, value, note) VALUES ('island.border.enforce', 'bool', 'true', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.border.enter-messages', 'bool', 'true', 'Send a chat line when a player enters or leaves an island.');
INSERT INTO setting (id, type, value, note) VALUES ('island.void.rescue', 'bool', 'true', 'Falling below the world: return safely within Skyblock instead of dying.');
INSERT INTO setting (id, type, value, note) VALUES ('island.void.message', 'text', 'You fell into the void and were pulled back to safety.', 'Tell the player.');
INSERT INTO setting (id, type, value, note) VALUES ('island.respawn.mode', 'text', 'HOME', 'Legacy field: per-mode beds and personal-island fallback now own all Skyblock respawns.');
INSERT INTO setting (id, type, value, note) VALUES ('island.portals.nether', 'bool', 'true', '1:1 coordinates between sb_world and sb_nether. Skyblock End portals are always blocked.');
INSERT INTO setting (id, type, value, note) VALUES ('island.portals.end', 'bool', 'true', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.portals.shortcuts', 'bool', 'true', '/is nether shortcut (no portal needed, the platforms must be ready). Cooldown in seconds.');
INSERT INTO setting (id, type, value, note) VALUES ('island.portals.shortcut-cooldown-seconds', 'int', '10', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.invites.expire-seconds', 'int', '120', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.invites.max-pending-per-player', 'int', '5', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.reset.cooldown-minutes', 'int', '60', 'Minimum time between two resets of the same island.');
INSERT INTO setting (id, type, value, note) VALUES ('island.reset.confirm-seconds', 'int', '30', 'Time allowed to type the confirmation.');
INSERT INTO setting (id, type, value, note) VALUES ('island.create.cooldown-minutes', 'int', '0', 'Cooldown before a player who lost their island may create a new one (minutes).');
INSERT INTO setting (id, type, value, note) VALUES ('island.level.divisor', 'real', '100.0', 'level = floor(total weighted value / divisor)');
INSERT INTO setting (id, type, value, note) VALUES ('island.level.auto-interval-minutes', 'int', '30', 'Automatic re-scan of online owners'' islands, in minutes (0 = off) and the cooldown for /is level in seconds.');
INSERT INTO setting (id, type, value, note) VALUES ('island.level.manual-cooldown-seconds', 'int', '300', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.level.chunks-per-tick', 'int', '2', 'Chunk snapshots taken per tick.');
INSERT INTO setting (id, type, value, note) VALUES ('island.level.default-weight', 'real', '0.0', 'Blocks not listed count for this much.');
INSERT INTO setting (id, type, value, note) VALUES ('island.warps.max-name-length', 'int', '24', '');
INSERT INTO setting (id, type, value, note) VALUES ('island.warps.cooldown-seconds', 'int', '5', 'Warps shown per page in the browser come from the menu size; this is the cooldown between warp teleports (seconds).');
INSERT INTO setting (id, type, value, note) VALUES ('island.commands.visit-cooldown-seconds', 'int', '3', 'Seconds between two /is visit or /is warp teleports of the same player.');
